const cantidadEstrellas=window.innerWidth<600?40:100;for(let i=0;i<cantidadEstrellas;i++){let e=document.createElement("div");e.className="estrella",e.style.top=Math.random()*window.innerHeight+"px",e.style.left=Math.random()*window.innerWidth+"px",document.body.appendChild(e)}function mostrarSorpresa(){document.getElementById("sorpresa").style.display="block"}let indice=0;const imagenes=document.querySelectorAll(".carrusel img"),frases=["Contigo todo es mejor 💕","Eres mi alegría 🌹","Siempre en mi corazón ✨","Mi lugar favorito: a tu lado 💖","Tu sonrisa ilumina mi día 🌼","Cada instante contigo es único 💎","Te pienso, te extraño, te amo 💘","Eres mi razón de vivir 🌙"];function avanzarImagen(){imagenes[indice].classList.remove("active"),indice=(indice+1)%imagenes.length,imagenes[indice].classList.add("active"),document.getElementById("frase").innerHTML=frases[indice]}function retrocederImagen(){imagenes[indice].classList.remove("active"),indice=(indice-1+imagenes.length)%imagenes.length,imagenes[indice].classList.add("active"),document.getElementById("frase").innerHTML=frases[indice]}let inicioX=0;const carrusel=document.querySelector(".carrusel");carrusel.addEventListener("touchstart",e=>inicioX=e.touches[0].clientX),carrusel.addEventListener("touchend",e=>{let t=e.changedTouches[0].clientX;inicioX-t>50&&avanzarImagen(),t-inicioX>50&&retrocederImagen()}),setInterval(avanzarImagen,3e3);function crearCorazon(){const e=document.createElement("div");e.className="corazon-flotante",e.innerHTML="❤️",e.style.left=Math.random()*window.innerWidth+"px",document.body.appendChild(e);let t=null;function n(r){t||(t=r);const o=(r-t)/6e3;e.style.transform=`translateY(${(1-o)*window.innerHeight}px)`,o<1?requestAnimationFrame(n):e.remove()}requestAnimationFrame(n)}setInterval(crearCorazon,window.innerWidth<600?1500:800);function crearFlor(){const e=document.createElement("div");e.className="flor-amarilla",e.innerHTML="🌼",e.style.left=Math.random()*window.innerWidth+"px",document.body.appendChild(e),setTimeout(()=>{e.remove()},8e3)}setInterval(crearFlor,2500);function lluviaSorpresa(){for(let e=0;e<50;e++)setTimeout(()=>{const t=document.createElement("div");t.style.position="absolute",t.style.left=Math.random()*window.innerWidth+"px",t.style.top=Math.random()*window.innerHeight+"px",t.style.fontSize="25px",t.style.animation="flotar 6s linear infinite",t.innerHTML=Math.random()>.5?"❤️":"✨",document.body.appendChild(t),setTimeout(()=>{t.remove()},6e3)},100*e);setTimeout(()=>{document.getElementById("overlay").style.display="block",document.getElementById("mensajeFinal").style.display="block"},6e3)}